namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Integration;
public sealed class AstronomyKnowledgeFoundationCapabilities:IAstronomyKnowledgeFoundationCapabilities
{ readonly IReadOnlyDictionary<AstronomyKnowledgeFoundationCapabilityId,AstronomyKnowledgeFoundationCapabilityDescriptor> byId; public AstronomyKnowledgeFoundationCapabilities(AstronomyKnowledgeFoundationCapabilitySnapshot snapshot){Snapshot=snapshot??throw new ArgumentNullException(nameof(snapshot)); byId=Snapshot.Capabilities.ToDictionary(c=>c.Id);} public AstronomyKnowledgeFoundationCapabilitySnapshot Snapshot{get;} public bool TryGet(AstronomyKnowledgeFoundationCapabilityId id,out AstronomyKnowledgeFoundationCapabilityDescriptor descriptor)=>byId.TryGetValue(id,out descriptor!); public IReadOnlyList<AstronomyKnowledgeFoundationCapabilityDescriptor> GetByKind(AstronomyKnowledgeFoundationCapabilityKind kind){ if(!Enum.IsDefined(kind)) throw new ArgumentOutOfRangeException(nameof(kind)); return kind switch{AstronomyKnowledgeFoundationCapabilityKind.TypedKnowledge=>Snapshot.TypedKnowledge,AstronomyKnowledgeFoundationCapabilityKind.Validation=>Snapshot.Validation,AstronomyKnowledgeFoundationCapabilityKind.CrossDomainValidation=>Snapshot.CrossDomainValidation,AstronomyKnowledgeFoundationCapabilityKind.GraphValidation=>Snapshot.GraphValidation,AstronomyKnowledgeFoundationCapabilityKind.Catalog=>Snapshot.Catalog,AstronomyKnowledgeFoundationCapabilityKind.QueryModel=>Snapshot.QueryModel,AstronomyKnowledgeFoundationCapabilityKind.QueryExecution=>Snapshot.QueryExecution,_=>throw new ArgumentOutOfRangeException(nameof(kind))};}}
